gVM(){return"\u0939\u0930 \u0928\u093f\u092a\u091f\u093e\u092f\u093e \u0917\u092f\u093e \u091a\u0947\u0915 \u0909\u0928 \u0932\u0947\u091c\u0930 \u092a\u094d\u0930\u0935\u093f\u0937\u094d\u091f\u093f\u092f\u094b\u0902 \u0938\u0947 \u091c\u0941\u0921\u093c\u093e \u0939\u0948 \u091c\u093f\u0928\u0915\u093e \u0935\u0939 \u092a\u094d\u0930\u0924\u093f\u0928\u093f\u0927\u093f\u0924\u094d\u0935 \u0915\u0930\u0924\u093e \u0939\u0948\u0964"},
VN(a){var s=null
return A.aH(a,s,this.a,s,"1 \u0928\u093f\u092a\u091f\u093e\u092f\u093e \u0917\u092f\u093e \u091a\u0947\u0915",""+a+" \u0928\u093f\u092a\u091f\u093e\u090f \u0917\u090f \u091a\u0947\u0915",s,s)+" \u2014 \u091c\u094d\u092f\u093e\u0926\u093e\u0924\u0930 Manager.io \u0938\u0947 \u0906\u092f\u093e\u0924\u093f\u0924 \u2014 \u0909\u0928 \u0932\u0947\u091c\u0930 \u092a\u094d\u0930\u0935\u093f\u0937\u094d\u091f\u093f\u092f\u094b\u0902 \u0938\u0947 \u0928\u0939\u0940\u0902 \u091c\u0941\u0921\u093c\u0947 \u0939\u0948\u0902 \u091c\u093f\u0928\u0915\u093e \u0935\u0947 \u092a\u094d\u0930\u0924\u093f\u0928\u093f\u0927\u093f\u0924\u094d\u0935 \u0915\u0930\u0924\u0947 \u0939\u0948\u0902\u0964 \u0905\u092d\u0940 \u090f\u0915 \u0915\u094b \u0939\u091f\u093e\u0928\u0947 \u0938\u0947 \u0915\u0947\u0935\u0932 \u0926\u093f\u0916\u093e\u0908 \u0926\u0947\u0928\u0947 \u0935\u093e\u0932\u093e \u091a\u0947\u0915 \u0939\u091f \u091c\u093e\u090f\u0917\u093e, \u0907\u0938\u0915\u0947 \u0935\u093e\u0938\u094d\u0924\u0935\u093f\u0915 \u092a\u0948\u0938\u0947 (\u0926\u0947\u092f, \u092a\u094d\u0930\u093e\u092a\u094d\u092f, \u0928\u0915\u0926 \u0914\u0930 \u092c\u0948\u0902\u0915) \u092a\u0942\u0930\u0940 \u0924\u0930\u0939 \u0938\u0947 \u0905\u091b\u0942\u0924\u0947 \u0930\u0939 \u091c\u093e\u090f\u0902\u0917\u0947\u0964 \u0939\u0930 \u090f\u0915 \u0915\u094b \u0909\u0938\u0915\u0940 \u0935\u093e\u0938\u094d\u0924\u0935\u093f\u0915 \u092a\u094d\u0930\u0935\u093f\u0937\u094d\u091f\u093f\u092f\u094b\u0902 \u0938\u0947 \u091c\u094b\u0921\u093c\u0924\u093e \u0939\u0948 \u0924\u093e\u0915\u093f \u0905\u092c \u0938\u0947 \u0939\u091f\u093e\u0928\u093e \u0938\u0939\u0940 \u0922\u0902\u0917 \u0938\u0947 \u0915\u093e\u092e \u0915\u0930\u0947 \u2014 \u0916\u0941\u0926 \u0915\u094b\u0908 \u092a\u0948\u0938\u093e \u0928\u0939\u0940\u0902 \u0939\u093f\u0932\u093e\u0924\u093e\u0964"},
gV2(){return"\u0932\u093f\u0902\u0915"},
gV6(){return"\u092c\u093f\u0928\u093e \u0928\u093f\u092f\u0924 \u0924\u093e\u0930\u0940\u0916 \u0935\u093e\u0932\u0947 \u091a\u093e\u0932\u093e\u0928"},
gV4(){return"\u0939\u0930 \u091a\u093e\u0932\u093e\u0928 \u0915\u0940 \u090f\u0915 \u0928\u093f\u092f\u0924 \u0924\u093e\u0930\u0940\u0916 \u0939\u094b\u0924\u0940 \u0939\u0948, \u0907\u0938\u0932\u093f\u090f \u0921\u0948\u0936\u092c\u094b\u0930\u094d\u0921 \u092a\u0930 \u0905\u0924\u093f\u0926\u0947\u092f/\u091c\u0932\u094d\u0926 \u0926\u0947\u092f \u0938\u091f\u0940\u0915 \u0939\u0948\u0902\u0964"},
V5(a){var s=null
return A.aH(a,s,this.a,s,"1 \u091a\u093e\u0932\u093e\u0928",""+a+" \u091a\u093e\u0932\u093e\u0928",s,s)+" \u2014 \u091c\u094d\u092f\u093e\u0926\u093e\u0924\u0930 Manager.io \u0938\u0947 \u0906\u092f\u093e\u0924\u093f\u0924 \u2014 \u0915\u0940 \u0915\u094b\u0908 \u0928\u093f\u092f\u0924 \u0924\u093e\u0930\u0940\u0916 \u0938\u0947\u091f \u0928\u0939\u0940\u0902 \u0939\u0948, \u0907\u0938\u0932\u093f\u090f \u0935\u0947 \u0921\u0948\u0936\u092c\u094b\u0930\u094d\u0921 \u092a\u0930 \u0915\u092d\u0940 \u0905\u0924\u093f\u0926\u0947\u092f \u092f\u093e \u091c\u0932\u094d\u0926 \u0926\u0947\u092f \u0915\u0947 \u0930\u0942\u092a \u092e\u0947\u0902 \u0928\u0939\u0940\u0902 \u0926\u093f\u0916\u0924\u0947\u0964 \u092a\u094d\u0930\u0924\u094d\u092f\u0947\u0915 \u0915\u094b \u0909\u0938\u0915\u0947 \u0917\u094d\u0930\u093e\u0939\u0915 \u0915\u0940 \u0915\u094d\u0930\u0947\u0921\u093f\u091f \u0936\u0930\u094d\u0924\u094b\u0902 (\u0928\u0915\u0926, \u092c\u093f\u0932-\u091f\u0942-\u092c\u093f\u0932, \u0926\u093f\u0928, \u092f\u093e \u0916\u0941\u0932\u093e) \u0938\u0947 \u0938\u0947\u091f \u0915\u0930\u0924\u093e \u0939\u0948 \u2014 \u0915\u093f\u0938\u0940 \u092d\u0940 \u0926\u0947\u092f \u0930\u093e\u0936\u093f \u0915\u094b \u0928\u0939\u0940\u0902 \u092c\u0926\u0932\u0924\u093e\u0964"},
gVD(){return"\u0928\u093f\u092f\u0924 \u0924\u093e\u0930\u0940\u0916\u0947\u0902 \u0938\u0947\u091f \u0915\u0930\u0947\u0902"},
gVh(){return"\u092c\u091a\u0940 \u0939\u0941\u0908 \u092a\u0947\u0930\u094b\u0932 \u0932\u0947\u091c\u0930 \u092a\u094d\u0930\u0935\u093f\u0937\u094d\u091f\u093f\u092f\u093e\u0902"},
gVf(){return"\u0915\u093f\u0938\u0940 \u092d\u0940 \u092a\u0947\u0930\u094b\u0932 \u0930\u0928 \u0928\u0947 \u0905\u0928\u093e\u0925 \u0932\u0947\u091c\u0930 \u092a\u094d\u0930\u0935\u093f\u0937\u094d\u091f\u093f\u092f\u093e\u0902 \u092a\u0940\u091b\u0947 \u0928\u0939\u0940\u0902 \u091b\u094b\u0921\u093c\u0940 \u0939\u0948\u0902\u0964"},
Vg(a,b){var s=null
return A.aH(a,s,this.a,s,"1 \u0932\u0947\u091c\u0930 \u092a\u094d\u0930\u0935\u093f\u0937\u094d\u091f\u093f",""+a+" \u0932\u0947\u091c\u0930 \u092a\u094d\u0930\u0935\u093f\u0937\u094d\u091f\u093f\u092f\u093e\u0902",s,s)+" ("+b+") \u090f\u0915 \u092a\u0947\u0930\u094b\u0932 \u0930\u0928 \u0938\u0947 \u091c\u093f\u0938\u0947 \u0905\u092a\u0928\u0940 \u092a\u094b\u0938\u094d\u091f\u093f\u0902\u0917 \u0915\u094b \u0909\u0932\u091f\u0928\u0947 \u0938\u0947 \u092a\u0939\u0932\u0947 \u0939\u0940 \u0939\u091f\u093e \u0926\u093f\u092f\u093e \u0917\u092f\u093e \u0925\u093e \u2014 \u0905\u092d\u0940 \u092d\u0940 \u0928\u0915\u0926 \u0914\u0930 \u092c\u0948\u0902\u0915 \u092e\u0947\u0902 \u0926\u093f\u0916\u093e\u0908 \u0926\u0947 \u0930\u0939\u0940 \u0939\u0948\u0902 \u091c\u093f\u0928\u094d\u0939\u0947\u0902 \u0935\u0939\u093e\u0902 \u0938\u0947 \u0938\u0902\u092a\u093e\u0926\u093f\u0924 \u092f\u093e \u0939\u091f\u093e\u0928\u0947 \u0915\u093e \u0915\u094b\u0908 \u0924\u0930\u0940\u0915\u093e \u0928\u0939\u0940\u0902 \u0939\u0948\u0964 \u0920\u0940\u0915 \u0907\u0928\u094d\u0939\u0940\u0902 \u092a\u094d\u0930\u0935\u093f\u0937\u094d\u091f\u093f\u092f\u094b\u0902 \u0915\u094b \u0939\u091f\u093e\u0924\u093e \u0939\u0948; \u0915\u0930\u094d\u092e\u091a\u093e\u0930\u0940 \u0915\u093e \u0905\u092a\u0928\u093e \u0935\u0947\u0924\u0928 \u0936\u0947\u0937 \u092a\u094d\u0930\u092d\u093e\u0935\u093f\u0924 \u0928\u0939\u0940\u0902 \u0939\u094b\u0924\u093e\u0964"},
gUP(){return"\u0916\u0924\u0930\u0947 \u0915\u093e \u0915\u094d\u0937\u0947\u0924\u094d\u0930"},
